Method.Source:
/// <summary>
/// Trigger enable field, as module customer is default, want to make sure METInvoiceConsolidationByRebateType and METVendAccount are hidden
/// </summary>
public void init()
{
    next init();
    this.enableFields();
}

/// <summary>
/// Only show METInvoiceConsolidationByRebateType and METVendAccount when module is vendor
/// </summary>
public void enableFields()
{
    next enableFields();

    TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, METInvoiceConsolidationByRebateType)).visible(TAMRebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend);

    TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, METVendAccount)).visible(TAMRebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend);
    TAMRebateDeal_ds.object(fieldNum(TAMRebateDeal, METVendAccount)).mandatory(TAMRebateDeal.METInvoiceConsolidationByRebateType);
}
